CREATE TABLE users(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,last_login_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_users_email UNIQUE(email));
CREATE TABLE roles(id UUID PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL);
CREATE TABLE permissions(id UUID PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE user_roles(user_id UUID NOT NULL REFERENCES users(id),role_id UUID NOT NULL REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id UUID NOT NULL REFERENCES roles(id),permission_id UUID NOT NULL REFERENCES permissions(id),PRIMARY KEY(role_id,permission_id));
CREATE TABLE refresh_tokens(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),token_hash VARCHAR(64) NOT NULL UNIQUE,family_id UUID NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,revoked_at TIMESTAMP WITH TIME ZONE,replaced_by_token_id UUID REFERENCES refresh_tokens(id),created_at TIMESTAMP WITH TIME ZONE NOT NULL,last_used_at TIMESTAMP WITH TIME ZONE,user_agent VARCHAR(200));
CREATE INDEX idx_refresh_tokens_user_active ON refresh_tokens(user_id,revoked_at,expires_at);
CREATE INDEX idx_refresh_tokens_family ON refresh_tokens(family_id);
ALTER TABLE audit_events ADD COLUMN actor_user_id UUID REFERENCES users(id);
CREATE INDEX idx_audit_events_actor_user ON audit_events(actor_user_id);

